-- =====================================================
--  CANI SHOP — Costo de tus productos (solo lo ves tú en el panel)
--  Copia TODO, pégalo en Supabase → SQL Editor → Run. Se puede correr varias veces.
--  Los costos vienen de tu Excel de Kyte ("Costo unitario"). Si ya editaste un
--  costo en el panel, NO se pisa.
-- =====================================================

create table if not exists public.costos (
  id     text primary key references public.productos(id) on delete cascade,
  costo  numeric not null default 0 check (costo >= 0)
);

alter table public.costos enable row level security;
revoke all on public.costos from anon;
grant select, insert, update, delete on public.costos to authenticated;

drop policy if exists "solo admin ve costos" on public.costos;
create policy "solo admin ve costos" on public.costos
  for all to authenticated using (public.es_admin()) with check (public.es_admin());

